property.value:
(: Note: (: isWithin pattern :) pmd-kotlin:isWithin() does not exist in released PMD 7.28.0, experimental/future API.
   Replaced below with plain ancestor:: checks; see AvoidExcessiveClassloadingWithSaajSoap (remotingnextgen.xml)
   for more details. Grep for "(: isWithin pattern :)" to find/simplify all occurrences if isWithin() is ever
   actually released. :)
//PostfixUnaryExpression[
    PrimaryExpression/SimpleIdentifier/T-Identifier[@Text='synchronized']
    and PostfixUnarySuffix/CallSuffix
    and ancestor::FunctionBody
    and not(
        PostfixUnarySuffix/CallSuffix//LambdaLiteral//PostfixUnaryExpression[
            PrimaryExpression/SimpleIdentifier/T-Identifier/@Text =
                ancestor::ClassBody[1]//PropertyDeclaration[
                    not(ancestor::FunctionBody or ancestor::LambdaLiteral)
                ]/VariableDeclaration/@Identifier
        ]
    )
    and not(
        PostfixUnarySuffix/CallSuffix//LambdaLiteral//Assignment[
            (DirectlyAssignableExpression|AssignableExpression)//T-Identifier/@Text =
                ancestor::ClassBody[1]//PropertyDeclaration[
                    not(ancestor::FunctionBody or ancestor::LambdaLiteral)
                ]/VariableDeclaration/@Identifier
        ]
    )
]

rule.example:
class SyncService {
    fun bad(): String {
        var localVar = "start"
        synchronized(this) {
            localVar = "updated" // bad
        }
        return localVar
    }
}

fun collectBad(completionService: CompletionService<List<Any>>): Future<List<Any>> {
    return completionService.take() // bad
}

fun collectGood(completionService: CompletionService<List<Any>>): Future<List<Any>>? {
    return completionService.poll(3L, TimeUnit.SECONDS) // good
}

property.value:
//PostfixUnaryExpression[
    pmd-kotlin:matchesSig('java.util.concurrent.Future#get()')
    (: 'get' is a Kotlin soft keyword (property getter), tokenized as T-GET not T-Identifier; use a wildcard :)
    and ./PostfixUnarySuffix/NavigationSuffix/SimpleIdentifier/*[@Text='get']
]

rule.example:
fun bad(complFuture: CompletableFuture<String>): String {
    return complFuture.get() // bad
}

fun good(complFuture: CompletableFuture<String>): String {
    return complFuture.get(10, TimeUnit.SECONDS) // good
}

property.value:
//KotlinFile[
    ImportList/ImportHeader[
        starts-with(@Name, 'org.springframework.web.client')
        or starts-with(@Name, 'org.apache.commons.httpclient')
        or starts-with(@Name, 'org.apache.http')
    ]
]//PostfixUnaryExpression[
    pmd-kotlin:matchesSig('java.util.Collection#parallelStream()')
    and not(ancestor::LambdaLiteral[
        ancestor::PostfixUnaryExpression[pmd-kotlin:matchesSig('java.util.concurrent.ForkJoinPool#submit(*)')]
    ])
]

rule.example:

import org.springframework.web.client.RestTemplate
class Service(val restTemplate: RestTemplate) {
    val items = listOf("a", "b")
    fun bad() = items.parallelStream().forEach { restTemplate.getForObject("/api/$it", String::class.java) } // bad: blocks common pool
    fun good() = kotlinx.coroutines.runBlocking { items.map { kotlinx.coroutines.async(kotlinx.coroutines.Dispatchers.IO) { restTemplate.getForObject("/api/$it", String::class.java) } }.map { it.await() } } // ok: IO dispatcher
}

import java.util.concurrent.Callable
import java.util.concurrent.ExecutorService
import java.util.concurrent.Future
import java.util.concurrent.TimeUnit

class TaskRunner {
    fun invokeAllBad(executor: ExecutorService, callables: Collection<Callable<String>>): List<Future<String>> {
        return executor.invokeAll(callables) // bad
    }

    fun invokeAllGood(executor: ExecutorService, callables: Collection<Callable<String>>): List<Future<String>> {
        return executor.invokeAll(callables, 30, TimeUnit.SECONDS) // good
    }
}

class StreamService {
    fun bad(list: List<String>) {
        list.parallelStream().forEach { println(it) } // bad
    }

    fun good(list: List<String>) {
        list.asSequence().forEach { println(it) } // good
    }
}
